import sys, json

msgs = []
for line in sys.stdin:
    obj = json.loads(line)
    if obj.get('type') == 'message':
        msgs.append(obj)

# Show a high-level timeline of all messages: role, tool name/id, timestamp, first 150 chars
for i, m in enumerate(msgs):
    msg = m['message']
    role = msg.get('role','?')
    ts = m.get('timestamp','')
    content = msg.get('content','')
    summary = ''
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict):
                t = c.get('type','')
                if t == 'text':
                    parts.append(f'TEXT:{c[\"text\"][:100]}')
                elif t == 'toolCall':
                    parts.append(f'CALL:{c.get(\"name\",\"?\")}({json.dumps(c.get(\"arguments\",{}))[:100]})')
                elif t == 'toolResult':
                    res_content = c.get('content','')
                    if isinstance(res_content, list):
                        res_text = ' '.join(str(rc)[:50] for rc in res_content[:2])
                    else:
                        res_text = str(res_content)[:100]
                    parts.append(f'RESULT:{c.get(\"toolName\",\"?\")}:{res_text[:80]}')
                elif t == 'thinking':
                    parts.append(f'THINK:{c.get(\"thinking\",\"\")[:100]}')
        summary = ' | '.join(parts)
    else:
        summary = str(content)[:200]
    print(f'{i:4d} {role:12s} {ts} {summary[:250]}')
